import{_ as o,c as a,o as t,ae as i}from"./chunks/framework.CHDT0Kbg.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1795170900000}'),r={name:"guide/troubleshooting.md"};function n(s,e,l,d,h,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Fixes for the problems you might run into.</p><h2 id="a-page-won-t-load" tabindex="-1">A page won&#39;t load <a class="header-anchor" href="#a-page-won-t-load" aria-label="Permalink to &quot;A page won&#39;t load&quot;">​</a></h2><ul><li>Check that other sites open, then try reloading with ⌘R.</li><li>If you enabled an ad-blocking rule list, pause it for a moment to see whether it is blocking this site.</li><li>Try a private window (⌘⇧N). If the page works there, clear the site&#39;s cookies from the cookie manager.</li></ul><h2 id="a-download-is-stuck-or-incomplete" tabindex="-1">A download is stuck or incomplete <a class="header-anchor" href="#a-download-is-stuck-or-incomplete" aria-label="Permalink to &quot;A download is stuck or incomplete&quot;">​</a></h2><ul><li>Open the download panel and pause, then resume the item.</li><li>For videos saved from a page, delete the partial file and try again. Split videos are joined into one MP4; a failed join leaves the original pieces in the download folder.</li></ul><h2 id="bookmarks-did-not-import" tabindex="-1">Bookmarks did not import <a class="header-anchor" href="#bookmarks-did-not-import" aria-label="Permalink to &quot;Bookmarks did not import&quot;">​</a></h2><p>Export bookmarks to an HTML file from your old browser first, then in Persim open the bookmark manager and choose <strong>Import HTML</strong>. Folders and duplicate links are handled for you.</p><h2 id="videos-are-not-detected" tabindex="-1">Videos are not detected <a class="header-anchor" href="#videos-are-not-detected" aria-label="Permalink to &quot;Videos are not detected&quot;">​</a></h2><p>Not every site exposes a video file. Open the media panel on the page you want; if nothing appears, the site may be streaming in a way that can&#39;t be saved directly.</p><h2 id="the-app-feels-slow" tabindex="-1">The app feels slow <a class="header-anchor" href="#the-app-feels-slow" aria-label="Permalink to &quot;The app feels slow&quot;">​</a></h2><p>Close tabs you are not using, or disable an ad-blocking subscription you no longer need. You can review site permissions in Settings.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Write to <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> with what you were doing and, if you can, a screenshot.</p>',14)])])}const m=o(r,[["render",n]]);export{u as __pageData,m as default};
